public interface Searchable extends Listable {
    boolean matches(String query);
}

import java.util.ArrayList;
import java.util.List;

public class Route extends Entry {
    protected boolean isFull;
    private int stopCount = 0;
    String code;
    private Stop[] stops = new Stop[5];
    private List<Ticket> sold = new ArrayList<>();

    public Route(String code, String from, String to) {
        this.code = code;
        addStop(from);
        addStop(to);
    }

    public void addStop(String name) {
        if (stopCount < 5) {
            stops[stopCount++] = new Stop(name);
        }
        isFull = stopCount == 5;
    }

    void sell(Ticket t) {
        sold.add(t);
    }

    @Override
    public boolean matches(String query) {
        return code.equals(query);
    }
}

public class Stop {
    private String name;

    public Stop(String name) {
        this.name = name;
    }

    public static boolean canAdd(Route r) {
        return !r.isFull;
    }
}

public class Ticket {
    private final Route route;
    private Ticket transfer;

    public Ticket(Route route) {
        this.route = route;
        route.sell(this);
    }

    public void setTransfer(Ticket next) {
        transfer = next;
    }
}

